<style>
    .shared-shell { min-height:100vh; padding:26px clamp(18px,12vw,260px) 60px; }.shared-header,.shared-note { width:100%; max-width:1440px; margin:auto; }.shared-header { display:flex; align-items:center; justify-content:space-between; gap:16px; padding:0 2px 20px; color:var(--muted); font-size:13px; }.shared-brand { color:var(--accent); font-weight:800; letter-spacing:-.03em; }.shared-header-right { display:flex; align-items:center; gap:12px; }.shared-note { padding:clamp(22px,5vw,52px); border:1px solid var(--line); border-radius:17px; background:var(--paper); box-shadow:0 18px 50px #10182818; }.shared-note h1 { margin:0; font-size:clamp(27px,5vw,39px); letter-spacing:-.045em; }.shared-path { margin:7px 0 32px; color:var(--muted); font-size:13px; }.shared-content { line-height:1.75; }.shared-content h2,.shared-content h3 { margin-top:1.7em; letter-spacing:-.035em; }.shared-content p,.shared-content ul,.shared-content ol { margin:1em 0; }.shared-content pre { overflow:auto; padding:14px; border-radius:9px; background:var(--preview); }.shared-content code { font-family:ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace; }.shared-content :not(pre) > code { display:inline-block; padding:.12em .38em; border:1px solid color-mix(in srgb,var(--line) 80%,var(--ink)); border-radius:5px; background:var(--preview); color:var(--ink); font:600 .88em/1.35 ui-monospace,SFMono-Regular,Menlo,Monaco,Consolas,monospace; box-shadow:inset 0 1px 0 color-mix(in srgb,var(--paper) 55%,transparent); }.shared-content a:not(.image-download) { color:var(--accent); font-weight:650; text-decoration:underline; text-decoration-thickness:1.5px; text-underline-offset:3px; }.shared-content img { display:block; max-width:100%; height:auto; }.note-image { position:relative; display:inline-block; max-width:100%; margin:.35em 0; vertical-align:top; }.image-download { position:absolute; z-index:1; top:9px; right:9px; display:grid; width:33px; height:33px; place-items:center; border:1px solid var(--line); border-radius:8px; background:var(--paper); color:var(--ink); box-shadow:0 5px 14px #10182835; opacity:0; transition:opacity .16s ease,transform .16s ease; transform:translateY(-3px); }.note-image:hover .image-download,.image-download:focus-visible { opacity:1; transform:translateY(0); }.image-download:focus-visible { outline:2px solid var(--accent); outline-offset:2px; }@media (hover:none) { .image-download { opacity:1; transform:translateY(0); } }@media (max-width:780px) { .shared-shell { padding:20px 16px 42px; } }.shared-theme { position:relative; }.shared-theme summary { cursor:pointer; list-style:none; border:1px solid var(--line); border-radius:8px; padding:5px 8px; color:var(--ink); background:var(--paper); }.shared-theme summary::-webkit-details-marker { display:none; }.shared-theme-menu { position:absolute; z-index:2; right:0; top:calc(100% + 7px); width:176px; padding:6px; border:1px solid var(--line); border-radius:10px; background:var(--paper); box-shadow:0 15px 35px #1018282e; }.shared-theme-menu button { display:block; width:100%; border:0; border-radius:7px; padding:7px 8px; background:transparent; color:var(--ink); text-align:left; font-size:13px; }.shared-theme-menu button:hover,.shared-theme-menu button.selected { background:var(--hover); }.shared-theme-menu button.selected::after { content:'✓'; float:right; color:var(--accent); font-weight:800; }
</style>
